<template>
  <base-layout>
    <v-toolbar v-if="authenticated" flat color="grey lighten-3" height="40">
      <v-toolbar-title>Selamat Datang {{user.username}}</v-toolbar-title>
    </v-toolbar>
  </base-layout>
</template>

<script>
export default {
  data() {
    return {};
  },
  created() {},
  computed: {
    authenticated() {
      return this.$store.state.auth.authenticated;
    },
    user() {
      return this.$store.state.auth.user;
    },
    windowSize() {
      return this.$store.state.app.windowSize;
    }
  }
};
</script>
<style scoped>
</style>



